mapper.insert:
INSERT INTO post_like (post_id, member_id)
VALUES (#{postId}, #{memberId})
ON DUPLICATE KEY UPDATE member_id = #{memberId}

mapper.delete:
DELETE FROM post_like
WHERE post_id = #{postId}
    AND member_id = #{memberId}

mapper.select:
SELECT COUNT(*)
FROM post_like
WHERE post_id = #{postId}

SELECT EXISTS (
    SELECT 1
    FROM post_like
    WHERE post_id = #{postId}
        AND member_id = #{memberId}
)
